(()=>{'use strict';
const $=id=>document.getElementById(id),D=window.MQ_I18N;
const store={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}},del(k){try{localStorage.removeItem(k)}catch{}}};
let lang=store.get('mq-language')||'en';if(!D[lang])lang='en';
let info=null,category='channels',preset=null,result=null,active=null,lastJob=null,working=false,started=0,timer=null;
const t=k=>D[lang][k]||D.en[k]||k,loc=o=>o?.[lang]||o?.en||'',esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,d=2)=>Number(x).toLocaleString({en:'en-GB',es:'es-ES',fr:'fr-FR',de:'de-DE'}[lang],{maximumFractionDigits:d}),ms=x=>x<1000?num(x,1)+' ms':num(x/1000,2)+' s';
function error(code,issues=[]){$('error').hidden=false;$('error').textContent=t(code)===code?t('error')+' ('+code+')':t(code);if(issues.length)$('error').textContent+=' '+issues.map(x=>x.field+': '+x.code).join('; ')}
function clearError(){$('error').hidden=true}
async function api(url,body,method){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),75000);try{const r=await fetch(url,{method:method||(body?'POST':'GET'),credentials:'same-origin',headers:{'Content-Type':'application/json','X-Metaquant-Request':'1'},body:body?JSON.stringify(body):undefined,signal:controller.signal});const d=await r.json();if(!r.ok){let e=new Error(typeof d.detail==='string'?d.detail:d.detail?.code||'invalid_problem_data');e.issues=d.detail?.issues||[];e.http=r.status;throw e}return d}finally{clearTimeout(timeout)}}
function controls(){const busy=working||!!active;$('run').disabled=busy||!info?.gpu_configured||!$('spec').value.trim();$('formulate').disabled=busy||!info?.meta_configured;$('validate').disabled=busy;$('intent').disabled=busy;$('spec').disabled=busy;document.querySelectorAll('#categories button,#examples button').forEach(b=>b.disabled=busy);$('cancel').hidden=!active;$('explain').disabled=busy||!result?.complete||!info?.meta_configured;$('export').disabled=!result;$('csv').disabled=!result?.engines?.traditional||!result?.engines?.quantum}
function status(code){$('status').textContent=t(code);$('status').classList.toggle('busy',working||!!active)}
function choose(p){preset=p;category=p.category;$('intent').value=loc(p.prompts);$('spec').value=JSON.stringify(p.spec,null,2);$('planMessage').textContent='';clearError();renderCatalog()}
function renderCatalog(){if(!info)return;$('categories').replaceChildren();for(const c of info.categories){const b=document.createElement('button');b.textContent=loc(c.title);b.className=category===c.id?'active':'';b.setAttribute('role','tab');b.setAttribute('aria-selected',String(category===c.id));b.onclick=()=>choose(info.presets.find(p=>p.category===c.id));$('categories').append(b)}const c=info.categories.find(x=>x.id===category);$('categoryTitle').textContent=loc(c.title);$('description').textContent=loc(c.description);$('limits').textContent=loc(c.limits);$('examples').replaceChildren();info.presets.filter(p=>p.category===category).forEach((p,i)=>{const b=document.createElement('button');b.textContent=t('scenario')+' '+(i+1);b.className=preset?.id===p.id?'active':'';b.onclick=()=>choose(p);$('examples').append(b)});const own=document.createElement('button');own.textContent=t('own');own.onclick=()=>{preset=null;$('intent').value='';$('intent').placeholder=t('ownHint');$('spec').value=JSON.stringify(c.template,null,2);$('planMessage').textContent=t('ownHint');renderCatalog();$('intent').focus()};$('examples').append(own);$('scale').textContent=preset?num(preset.spec.size,0)+' '+t('variables')+' · '+t('synthetic'):'';controls()}
function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));document.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));if(preset&&!active)$('intent').value=loc(preset.prompts);renderCatalog();if(result)renderResult();if(!active&&!working)status('ready');renderConnection()}
function renderConnection(){if(!info)return;$('connection').textContent=(info.gpu_configured?t('configured'):t('noGPU'))+' · '+(info.meta_configured?t('aiAvailable'):t('aiUnavailable'));if(!info.gpu_configured&&!active)status('missing')}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function renderResult(){if(!result)return;const r=result;$('runSummary').textContent=num(r.problem.variables,0)+' '+t('variables')+' · '+(r.problem.data_source==='synthetic'?t('synthetic'):'User data');for(const name of ['traditional','quantum']){const e=r.engines[name];if(!e)continue;$(name==='traditional'?'cpuState':'gpuState').textContent=t('done');let metrics=Object.entries(e.decoded.metrics).map(([k,v])=>`<div class="metric-detail"><span>${esc(metricLabel(k))}</span><strong>${esc(num(v,3))}</strong></div>`).join('');$(name).innerHTML=`<div class="metrics"><div><span class="value">${esc(ms(e.solver_ms))}</span><span class="label">${esc(t('time'))}</span></div><div><span class="value">${esc(num(e.energy,3))}</span><span class="label">${esc(t('cost'))}</span></div></div><p class="small muted">${esc(t('median'))}: ${esc(ms(e.median_ms))}</p><span class="valid ${e.decoded.feasible?'':'invalid'}">${esc(t(e.decoded.feasible?'feasible':'infeasible'))}</span>${metrics}<p class="small muted">${esc(t('groupA'))}: ${esc(e.decoded.selected.slice(0,12).map(v=>typeof v==='object'?JSON.stringify(v):v).join(', '))}${e.decoded.selected.length>12?'…':''}</p>${e.decoded.other_group.length?`<p class="small muted">${esc(t('groupB'))}: ${esc(e.decoded.other_group.slice(0,12).join(', '))}…</p>`:''}<p class="small">${esc(t(e.at_proven_optimum?'optimum':'unknown'))}</p>`;document.querySelector('[data-download="'+name+'"]').hidden=false}if(r.complete){const ratio=r.comparison.sb_speed_ratio,fast=ratio>=1?t('gpu'):t('cpu');$('comparison').textContent=fast+' · '+num(ratio>=1?ratio:1/ratio)+'× '+t('faster')+'. '+t('different')}else $('comparison').textContent=t('waiting');$('evidence').textContent=JSON.stringify({problem:r.problem,reference:r.reference,protocol:r.protocol,comparison:r.comparison,hardware:r.hardware},null,2);$('hardware').textContent=JSON.stringify(r.hardware,null,2);controls()}
function metricLabel(k){const labels={remaining_interference:['Audience conflict cost','Coste de conflicto de público'],avoided_interference:['Avoided conflicts','Conflictos evitados'],channel_1_count:['Session A events','Eventos sesión A'],channel_2_count:['Session B events','Eventos sesión B'],load_a:['Zone A load','Carga zona A'],load_b:['Zone B load','Carga zona B'],load_difference:['Load difference','Diferencia de carga'],contention_cost:['Resource contention','Competencia por recursos'],balance_cost:['Balance cost','Coste de equilibrio'],benefit:['Restoration value','Valor de restauración'],pair_cost:['Interaction cost','Coste de interacción'],net_value:['Net value','Valor neto'],selected_count:['Selected actions','Actuaciones seleccionadas'],execution_cost:['Handling cost','Coste de manipulación'],interaction_cost:['Pairwise transport cost','Coste entre parejas'],pool_a_count:['Hub A shipments','Pedidos centro A'],pool_b_count:['Hub B shipments','Pedidos centro B']};return labels[k]?.[lang==='es'?1:0]||k.replaceAll('_',' ')}
function pending(){result=null;lastJob=null;for(const n of ['traditional','quantum']){$(n).innerHTML='<div class="empty">'+esc(t('running'))+'</div>';document.querySelector('[data-download="'+n+'"]').hidden=true}$('cpuState').textContent='';$('gpuState').textContent='';$('comparison').textContent='';$('explanation').textContent=t('explanationHint');$('evidence').textContent='';$('export').disabled=true;$('csv').disabled=true}
function finish(){lastJob=active;active=null;store.del('mq-active');controls()}
async function poll(){if(!active)return;const id=active;try{const job=await api('/api/jobs/'+id);if(active!==id)return;if(job.partial){result=job.partial;renderResult()}if(job.status==='completed'){result=job.result;renderResult();finish();status('completed');$('status').textContent+=' · '+t('elapsed')+': '+ms(Date.now()-started)}else if(['failed','cancelled'].includes(job.status)){finish();status(job.stage);if(job.status==='failed')error(job.error||'compute_failed')}else{status(job.stage);if(['connecting','warming_up'].includes(job.stage)){const remaining=Math.max(0,90-Math.floor((Date.now()-started)/1000));$('status').textContent+=' · '+(remaining?remaining+' s':t('still'))}timer=setTimeout(poll,1500)}}catch(e){if(e.http===404){finish();status('job_expired');error(e.message)}else{$('status').textContent=t('error');timer=setTimeout(poll,4000)}}}
$('formulate').onclick=async()=>{if(working||active)return;clearError();working=true;controls();status('planning');try{const r=await api('/api/plan',{question:$('intent').value,language:lang});$('planMessage').textContent=r.message;if(r.status==='ready'){$('spec').value=JSON.stringify(r.spec,null,2);preset=null;category=info.categories.some(c=>c.id===r.spec.kind)?r.spec.kind:'custom';renderCatalog();$('planDetails').open=true;$('planMessage').textContent+=' '+t('planReady')}else{$('planDetails').open=false;$('spec').value=''}}catch(e){error(e.message,e.issues)}finally{working=false;controls();status('ready')}};
$('intent').addEventListener('input',()=>{preset=null;$('spec').value='';$('planMessage').textContent=t('ownHint');controls()});
$('spec').addEventListener('input',controls);
$('validate').onclick=async()=>{working=true;controls();clearError();try{const d=await api('/api/validate',{question:$('spec').value,language:lang});$('spec').value=JSON.stringify(d.spec,null,2);$('planMessage').textContent=t('valid')}catch(e){error(e.message,e.issues)}finally{working=false;controls()}};
$('run').onclick=async()=>{if(working||active)return;clearError();working=true;controls();try{const checked=await api('/api/validate',{question:$('spec').value,language:lang});pending();const id=crypto.randomUUID();started=Date.now();active=id.replaceAll('-','');store.set('mq-active',JSON.stringify({id:active,started}));controls();status('connecting');await api('/api/jobs',{request_id:id,spec:checked.spec,language:lang});poll()}catch(e){if(e.http){if(active)finish();error(e.message,e.issues)}else if(active){poll()}else error(e.message)}finally{working=false;controls()}};
$('cancel').onclick=async()=>{if(!active)return;try{await api('/api/jobs/'+active+'/cancel',{});status('cancelling')}catch(e){error(e.message)}};
$('explain').onclick=async()=>{if(!lastJob||working)return;clearError();working=true;controls();$('explanation').textContent=t('explaining');try{const d=await api('/api/jobs/'+lastJob+'/explain',{});$('explanation').textContent=d.text;result.meta_explanation=d}catch(e){$('explanation').textContent='';error(e.message)}finally{working=false;controls()}};
$('export').onclick=()=>{if(result)download('metaquant-forge-measurement.json',result)};
$('csv').onclick=()=>{if(!result?.engines.traditional||!result?.engines.quantum)return;const a=result.engines.traditional.bits,b=result.engines.quantum.bits;download('metaquant-forge-decisions.csv','decision,cpu_binary,gpu_binary\n'+a.map((v,i)=>`${i+1},${v},${b[i]}`).join('\n')+'\n','text/csv;charset=utf-8')};
document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const name=b.dataset.download;if(result?.engines[name])download('metaquant-forge-'+name+'.json',{problem:result.problem,hardware:result.hardware,engine:result.engines[name],complete:result.complete})});
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;store.set('mq-language',lang);translate()});
$('technical').onclick=()=>$('technicalDialog').showModal();$('closeDialog').onclick=()=>$('technicalDialog').close();
async function init(){try{info=await api('/api/info');choose(info.presets[0]);translate();let saved;try{saved=JSON.parse(store.get('mq-active'))}catch{}if(saved&&/^[a-f0-9]{32}$/.test(saved.id)){active=saved.id;started=saved.started||Date.now();pending();controls();poll()}}catch(e){error(e.message);status('error')}}
translate();controls();init();
})();
